insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('aefa5030-cbdd-4109-b0e3-b0836a34231f', '322a0cd6-fa8c-43bd-87e2-08e7030d067d', $$inleiding: vrije val en parachute$$,
   $$wiskunde-a-havo-2022-ii-parachutespringen-context1.png$$,
   $$Bij parachutespringen spring je uit een vliegtuig. Eerst maak je enige tijd een vrije val. Tijdens die vrije val is de parachute nog niet geopend. Daarna open je de parachute en land je met een veilige snelheid op de grond.$$, 'inline'),
  ('32c76492-078c-4b90-8c1a-def6dac2ba33', '322a0cd6-fa8c-43bd-87e2-08e7030d067d', $$Bart: van 4000 m naar 1500 m in 50 seconden$$,
   $$wiskunde-a-havo-2022-ii-parachutespringen-context2.png$$,
   $$Bart springt op een hoogte van 4000 meter uit het vliegtuig en maakt dan een vrije val. Na 50 seconden is hij op 1500 meter hoogte en stopt de vrije val, omdat hij dan zijn parachute opent.$$, 'inline'),
  ('233ff905-91b2-4396-b847-eeedebdfb166', '322a0cd6-fa8c-43bd-87e2-08e7030d067d', $$theoretische vrije val: formule 1$$,
   $$wiskunde-a-havo-2022-ii-parachutespringen-context3.png$$,
   $$Tijdens de vrije val die Bart maakt, wordt hij afgeremd door de lucht. Daarom duurt de vrije val van Bart langer dan een theoretische vrije val over dezelfde afstand. Een theoretische vrije val is een val ten gevolge van de zwaartekracht zonder dat de val door de lucht wordt afgeremd. Voor de hoogte van een voorwerp tijdens een theoretische vrije val die begint op een hoogte van 4000 meter geldt de formule:
h = 4000 − 4,9 · t² (formule 1)
Hierin is h de hoogte van het voorwerp tijdens de theoretische vrije val (in meters) en t de tijd (in seconden) vanaf het moment dat de theoretische vrije val begint.$$, 'inline'),
  ('7054836e-cd1e-42fe-a5f7-8a8afa351a9b', '322a0cd6-fa8c-43bd-87e2-08e7030d067d', $$verschil in duur met de theoretische vrije val$$,
   $$wiskunde-a-havo-2022-ii-parachutespringen-context4.png$$,
   $$Er kan berekend worden hoeveel seconden de vrije val van Bart van 4000 meter naar 1500 meter langer duurt dan een theoretische vrije val over dezelfde afstand.$$, 'inline'),
  ('83a2cdce-8ac6-4ec7-8d8a-dd92a62ee76d', '322a0cd6-fa8c-43bd-87e2-08e7030d067d', $$globaal verloop van een parachutesprong$$,
   $$wiskunde-a-havo-2022-ii-parachutespringen-context5.png$$,
   $$Figuur 1 is een schets van het globale verloop van een parachutesprong. Nadat de parachutist uit het vliegtuig gesprongen is, maakt hij een vrije val. Zodra de parachute geopend is, neemt de snelheid in korte tijd flink af. Daarna wordt een constante valsnelheid bereikt. Dat wil zeggen: tot aan de landing heeft de parachutist dezelfde valsnelheid.$$, 'inline'),
  ('9972994b-f324-4702-ba25-a1322005bfd7', '322a0cd6-fa8c-43bd-87e2-08e7030d067d', $$figuur 1 en de constante valsnelheid v$$,
   $$wiskunde-a-havo-2022-ii-parachutespringen-context6.png$$,
   $$figuur 1
hoogte tegen tijd: afsprong, vrije val, parachute wordt geopend, val met geopende parachute
De constante valsnelheid op het laatste deel noemen we v (in meters per seconde). Deze snelheid is afhankelijk van de massa m (in kg) van de parachutist (in deze opgave is dat altijd inclusief kleding en parachute) en van de wrijvingscoëfficiënt W van de parachute. Deze wrijvingscoëfficiënt is een getal dat afhangt van onder andere de grootte, de vorm en het materiaal van de parachute. Zo geldt bijvoorbeeld: hoe groter de parachute, hoe groter de wrijvingscoëfficiënt. Bij een grotere wrijvingscoëfficiënt heb je meer wrijving met de lucht, waardoor je minder snel valt. In figuur 2 is voor een aantal waarden van de wrijvingscoëfficiënt W te zien hoe v afhangt van m. Deze figuur staat ook op de uitwerkbijlage.$$, 'inline'),
  ('ad30ef0c-7f32-438c-bd1f-99c0e6ec5a57', '322a0cd6-fa8c-43bd-87e2-08e7030d067d', $$figuur 2: v tegen m voor verschillende W$$,
   $$wiskunde-a-havo-2022-ii-parachutespringen-context7.png$$,
   $$figuur 2
v (m/s) (verticale as, 0 t/m 11) tegen m (kg) (horizontale as, 50 t/m 120); grafieken voor W = 10, W = 20, W = 30, W = 40 en W = 50$$, 'inline'),
  ('95234ff6-b23c-41d5-a53f-c8fb2b7b5788', '322a0cd6-fa8c-43bd-87e2-08e7030d067d', $$parachutisten met een massa van 90 kg$$,
   $$wiskunde-a-havo-2022-ii-parachutespringen-context8.png$$,
   $$We kijken nu naar parachutisten met een massa van 90 kg die sprongen maken met parachutes met verschillende wrijvingscoëfficiënten W.$$, 'inline'),
  ('06649cbb-c1fb-46a0-bea4-7cf5b68b87d2', '322a0cd6-fa8c-43bd-87e2-08e7030d067d', $$formule 2 voor de constante valsnelheid$$,
   $$wiskunde-a-havo-2022-ii-parachutespringen-context9.png$$,
   $$Bij figuur 2 hoort de volgende formule voor de constante valsnelheid:
v = 3,13 · √(m / w) (formule 2)
Hierin is v de constante valsnelheid in meters per seconde, m de massa van de parachutist in kg en W de wrijvingscoëfficiënt van de parachute.$$, 'inline'),
  ('9cc9baec-bc3d-443a-9107-f386b323f736', '322a0cd6-fa8c-43bd-87e2-08e7030d067d', $$Tina: 79 kg, W = 45, na 34 s op 1300 m$$,
   $$wiskunde-a-havo-2022-ii-parachutespringen-context10.png$$,
   $$Tina is een parachutist met een massa van 79 kg. De wrijvingscoëfficiënt van haar parachute is 45. Met deze parachute maakt zij een sprong. Precies 34 seconden na de afsprong is zij op 1300 meter hoogte en bereikt zij haar constante valsnelheid. Op dat moment start het laatste gedeelte van haar parachutesprong.$$, 'inline'),
  ('2a87b6e6-42cc-455c-881f-ad15f7006033', '322a0cd6-fa8c-43bd-87e2-08e7030d067d', $$parachute met W = 40: formule 3$$,
   $$wiskunde-a-havo-2022-ii-parachutespringen-context11.png$$,
   $$We kijken nu naar één bepaalde parachute met een wrijvingscoëfficiënt van 40. Personen met verschillende massa’s kunnen met deze parachute gaan springen. Formule 2 kan dan worden herleid tot de volgende vorm:
v = ... · √m (formule 3)$$, 'inline'),
  ('94b42d96-703a-4e78-9de0-66410c6a803f', '322a0cd6-fa8c-43bd-87e2-08e7030d067d', $$uitwerkbijlage vraag 3: figuur 2$$,
   $$wiskunde-a-havo-2022-ii-parachutespringen-context12.png$$,
   $$3
v (m/s) (verticale as, 0 t/m 11) tegen m (kg) (horizontale as, 50 t/m 120); grafieken voor W = 10, W = 20, W = 30, W = 40 en W = 50$$, 'uitwerkbijlage'),
  ('0392c592-df8b-463f-92b3-8de30a1c3848', 'bac1b2a5-9c72-4215-a361-ffaff53f2412', $$inleiding: A1-, A2- en B-ritten$$,
   $$wiskunde-a-havo-2022-ii-spoedeisende-ritten-van-ambulances-context1.png$$,
   $$De ambulancezorg is in Nederland per regio georganiseerd. Er zijn 25 regio’s. Elke regio heeft zijn eigen Regionale Ambulancevoorziening (RAV). Elke RAV beschikt over een aantal ambulances en een meldkamer.
Wanneer er een melding bij de meldkamer binnenkomt, moet men de mate van urgentie van de melding vaststellen en zorgen voor de inzet van een ambulance: een ambulancerit. De mate van urgentie kan zijn: − Hoge urgentie: de benodigde zorg is spoedeisend en er is sprake van direct levensgevaar voor de patiënt. We noemen dit een A1-rit. − Lage urgentie: de benodigde zorg is spoedeisend, maar er is geen direct levensgevaar voor de patiënt. We noemen dit een A2-rit. − Geen urgentie: de benodigde zorg is niet spoedeisend. We noemen dit een B-rit.$$, 'inline'),
  ('881ed966-5288-4e2b-80d1-a729333a2a2b', 'bac1b2a5-9c72-4215-a361-ffaff53f2412', $$definitie responstijd$$,
   $$wiskunde-a-havo-2022-ii-spoedeisende-ritten-van-ambulances-context2.png$$,
   $$De responstijd is de tijd tussen het aannemen van de telefoon in de meldkamer en de aankomst van de ambulance bij de patiënt.$$, 'inline'),
  ('97c2f20a-6b51-4318-89ab-fc7e20fa34b8', 'bac1b2a5-9c72-4215-a361-ffaff53f2412', $$vier statistische variabelen$$,
   $$wiskunde-a-havo-2022-ii-spoedeisende-ritten-van-ambulances-context3.png$$,
   $$In een rapport over de ambulancezorg in Nederland spelen de volgende vier statistische variabelen een rol: − regio − mate van urgentie (van een melding bij de meldkamer) − aantal ambulanceritten (per jaar per regio) − responstijd (van een ambulancerit)$$, 'inline'),
  ('28dc308d-2af1-410e-9f16-1f07e5bc0961', 'bac1b2a5-9c72-4215-a361-ffaff53f2412', $$tabel met de variabelen op de uitwerkbijlage$$,
   $$wiskunde-a-havo-2022-ii-spoedeisende-ritten-van-ambulances-context4.png$$,
   $$Op de uitwerkbijlage staan deze vier variabelen in een tabel.$$, 'inline'),
  ('ffaee3ae-598f-481c-8445-507160b6ac1a', 'bac1b2a5-9c72-4215-a361-ffaff53f2412', $$A1-ritten hebben kortere responstijden dan A2-ritten$$,
   $$wiskunde-a-havo-2022-ii-spoedeisende-ritten-van-ambulances-context5.png$$,
   $$In de rest van de opgave kijken we alleen naar A1-ritten en A2-ritten. Omdat er bij A1-ritten sprake is van direct levensgevaar voor de patiënt, zijn de responstijden van deze ritten over het algemeen korter dan de responstijden van de A2-ritten.$$, 'inline'),
  ('1d2b2875-d03b-41e6-b1aa-68a27ad8c7c0', 'bac1b2a5-9c72-4215-a361-ffaff53f2412', $$relatieve cumulatieve frequentiepolygonen van de responstijden$$,
   $$wiskunde-a-havo-2022-ii-spoedeisende-ritten-van-ambulances-context6.png$$,
   $$In de figuur staan de relatieve cumulatieve frequentiepolygonen van de responstijden van de A1-ritten en die van de responstijden van de A2-ritten in 2014. De figuur staat twee keer op de uitwerkbijlage vergroot afgedrukt. In de figuur is niet aangegeven welke polygoon bij de A1-ritten hoort en welke bij de A2-ritten.$$, 'inline'),
  ('0451795a-331b-4117-8a61-cb451f1d106d', 'bac1b2a5-9c72-4215-a361-ffaff53f2412', $$figuur: twee cumulatieve frequentiepolygonen$$,
   $$wiskunde-a-havo-2022-ii-spoedeisende-ritten-van-ambulances-context7.png$$,
   $$figuur
cumulatief percentage (verticale as, 0 t/m 100) tegen responstijd (minuten) (horizontale as, 0 t/m 60); twee polygonen$$, 'inline'),
  ('7807976b-2b14-4e39-98ea-2869d82866f8', 'bac1b2a5-9c72-4215-a361-ffaff53f2412', $$formule P = 100 / (1 + 27 · aᵗ)$$,
   $$wiskunde-a-havo-2022-ii-spoedeisende-ritten-van-ambulances-context8.png$$,
   $$Het gedeelte van de rechter polygoon waarbij de responstijden tussen 18 en 30 minuten liggen, kan benaderd worden met de grafiek van een formule van de volgende vorm:
P = 100 / (1 + 27 · aᵗ)
Hierin is P het cumulatieve percentage, t de responstijd in minuten en a een getal.$$, 'inline'),
  ('ec8a44ed-28f4-40ed-95e9-c70eeb97f21c', 'bac1b2a5-9c72-4215-a361-ffaff53f2412', $$uitwerkbijlage vraag 6: tabel soorten variabelen$$,
   $$wiskunde-a-havo-2022-ii-spoedeisende-ritten-van-ambulances-context9.png$$,
   $$6
kolommen: kwantitatief (discreet | continu) | kwalitatief (nominaal | ordinaal)
rijen: regio | mate van urgentie (van een melding bij de meldkamer) | aantal ambulanceritten (per jaar per regio) | responstijd (van een ambulancerit)$$, 'uitwerkbijlage'),
  ('2bfabdcb-1cb8-4448-99b0-37bb07ac84c7', 'bac1b2a5-9c72-4215-a361-ffaff53f2412', $$uitwerkbijlage vraag 7 en 8: figuur (twee keer)$$,
   $$wiskunde-a-havo-2022-ii-spoedeisende-ritten-van-ambulances-context10.png$$,
   $$7
cumulatief percentage (verticale as, 0 t/m 100) tegen responstijd (minuten) (horizontale as, 0 t/m 60); twee polygonen
8
cumulatief percentage (verticale as, 0 t/m 100) tegen responstijd (minuten) (horizontale as, 0 t/m 60); twee polygonen$$, 'uitwerkbijlage'),
  ('01836c05-983e-4068-b89a-407510022c2e', '0e7d20c6-5ee6-4bec-80aa-740a1459049d', $$inleiding: B-formaat, B0 1000 mm bij 1414 mm$$,
   $$wiskunde-a-havo-2022-ii-b-papier-in-een-enveloppe-context1.png$$,
   $$Papier is er in verschillende soorten en maten. Een internationaal gebruikt formaat is het B-formaat. Bij dit formaat is een vel papier met een breedte van 1000 mm en een hoogte van 1414 mm als basisformaat gekozen. Dit is het zogenaamde B0-formaat. Als een vel papier met B0-formaat gehalveerd wordt, ontstaat een vel papier in B1-formaat, waarvan de afmetingen 707 mm bij 1000 mm zijn. Opnieuw halveren geeft een vel papier in B2-formaat, dat gehalveerd een vel papier in B3-formaat oplevert, enzovoorts. Zie de figuur.$$, 'inline'),
  ('7223487f-43be-4742-a542-ce7618ab4bb8', '0e7d20c6-5ee6-4bec-80aa-740a1459049d', $$figuur: B0 t/m B10$$,
   $$wiskunde-a-havo-2022-ii-b-papier-in-een-enveloppe-context2.png$$,
   $$figuur
B0-vel (1000 mm bij 1414 mm) verdeeld in B1 t/m B10; maten in de figuur: 1000 mm, 1414 mm en 707 mm$$, 'inline'),
  ('01c52f2c-6606-4a16-b280-3fb4ee42dc8a', '0e7d20c6-5ee6-4bec-80aa-740a1459049d', $$kleinste formaat is B10$$,
   $$wiskunde-a-havo-2022-ii-b-papier-in-een-enveloppe-context3.png$$,
   $$Het kleinste B-formaat dat gebruikt wordt, is het B10-formaat.$$, 'inline'),
  ('6896ccc9-bf33-43dc-a3e7-c1b8a1360f44', '0e7d20c6-5ee6-4bec-80aa-740a1459049d', $$oppervlakte = breedte × hoogte$$,
   $$wiskunde-a-havo-2022-ii-b-papier-in-een-enveloppe-context4.png$$,
   $$In de rest van deze opgave kijken we naar de oppervlakte van papier en enveloppen. Het gaat dan telkens om de oppervlakte van de voorkant. Er geldt: oppervlakte = breedte × hoogte.$$, 'inline'),
  ('56034e26-1517-4fbb-98b6-e2f1391ac6f9', '0e7d20c6-5ee6-4bec-80aa-740a1459049d', $$B4-formaat: oppervlakte 88 375 mm²$$,
   $$wiskunde-a-havo-2022-ii-b-papier-in-een-enveloppe-context5.png$$,
   $$De oppervlakte van een vel papier in B4-formaat is 88 375 mm². Om zo’n vel papier ongevouwen te versturen is een speciaal formaat enveloppe ontwikkeld, de zogenaamde EB4-enveloppe.$$, 'inline'),
  ('f44f24f2-3f76-485d-89c9-1fcae28a18a9', '0e7d20c6-5ee6-4bec-80aa-740a1459049d', $$EB4-enveloppe: b = 262 mm en h = 371 mm$$,
   $$wiskunde-a-havo-2022-ii-b-papier-in-een-enveloppe-context6.png$$,
   $$Een enveloppe in EB4-formaat heeft een breedte b van 262 mm en een hoogte h van 371 mm. De oppervlakte van deze enveloppe is groter dan de oppervlakte van een vel papier in B4-formaat.$$, 'inline'),
  ('5bd57b29-3bce-4352-8e30-721bafd595e6', '0e7d20c6-5ee6-4bec-80aa-740a1459049d', $$formule voor de hoogte h van enveloppe EBn$$,
   $$wiskunde-a-havo-2022-ii-b-papier-in-een-enveloppe-context7.png$$,
   $$Voor enveloppen EBn, waarin n het formaatnummer is, bestaan er formules voor de breedte en de hoogte. Voor de hoogte h in mm geldt de volgende formule:
h = 1484 · 2⁻⁽¹ᐟ²⁾ⁿ$$, 'inline'),
  ('e629eda2-798d-4f36-8ead-841d568a9d88', '0e7d20c6-5ee6-4bec-80aa-740a1459049d', $$formule voor de breedte b van enveloppe EBn$$,
   $$wiskunde-a-havo-2022-ii-b-papier-in-een-enveloppe-context8.png$$,
   $$Voor de breedte b in mm van enveloppen EBn, waarin n het formaatnummer is, geldt de volgende formule:
b = 1084 · 2⁻⁽¹ᐟ²⁾ⁿ
Hoe groter het formaatnummer, des te kleiner is de breedte van de enveloppe.$$, 'inline'),
  ('3f5236b3-cacc-445e-8854-836b0d3de89c', '98610a79-25e7-4def-9097-3ba6b2a52add', $$inleiding: persoonlijke recordtijden van 86 schaatssters$$,
   $$wiskunde-a-havo-2022-ii-recordtijden-van-schaatssters-context1.png$$,
   $$In deze opgave vergelijken we de prestaties van schaatssters, ook al hebben die schaatssters nooit in hetzelfde toernooi geschaatst. Hiervoor maken we gebruik van de persoonlijke recordtijden van schaatssters op zes verschillende afstanden, namelijk de 500, 1000, 1500, 3000, 5000 en 10 000 meter. In deze opgave beperken we ons tot 86 topschaatssters en hun persoonlijke recordtijden zoals die begin 2016 bekend waren.$$, 'inline'),
  ('a20fdb9f-ece7-403e-81c1-bc785ab3772f', '98610a79-25e7-4def-9097-3ba6b2a52add', $$spreidingsdiagram 500 m en 1000 m$$,
   $$wiskunde-a-havo-2022-ii-recordtijden-van-schaatssters-context2.png$$,
   $$De persoonlijke recordtijden van deze 86 schaatssters op de 500 meter en op de 1000 meter zijn weergegeven in een spreidingsdiagram. Zie figuur 1. Elke stip geeft één schaatsster weer. Deze figuur staat ook twee keer op de uitwerkbijlage.$$, 'inline'),
  ('7d0b8d2a-a921-4e98-889b-6e667c60c183', '98610a79-25e7-4def-9097-3ba6b2a52add', $$figuur 1: spreidingsdiagram$$,
   $$wiskunde-a-havo-2022-ii-recordtijden-van-schaatssters-context3.png$$,
   $$figuur 1
spreidingsdiagram: tijd op de 1000 meter (seconden) (verticale as, 73 t/m 91) tegen tijd op de 500 meter (seconden) (horizontale as, 37 t/m 47)$$, 'inline'),
  ('bb101765-0cb5-40c4-8d75-9d7db851f37e', '98610a79-25e7-4def-9097-3ba6b2a52add', $$uitspraken a, b en c over het spreidingsdiagram$$,
   $$wiskunde-a-havo-2022-ii-recordtijden-van-schaatssters-context4.png$$,
   $$Bij het spreidingsdiagram worden de volgende uitspraken gedaan over de resultaten van deze 86 schaatssters:
a Meer dan 90% van de schaatssters heeft de 500 meter afgelegd in minder dan 45,0 seconden.
b De mediaan van de tijd op de 1000 meter is ongeveer 81,5 seconden.
c De drie snelste schaatssters op de 500 meter zijn ook de drie snelste schaatssters op de 1000 meter.$$, 'inline'),
  ('57297a47-6058-40f5-a0dd-9a69387452bc', '98610a79-25e7-4def-9097-3ba6b2a52add', $$omrekenen naar gemiddelde tijd per 500 meter$$,
   $$wiskunde-a-havo-2022-ii-recordtijden-van-schaatssters-context5.png$$,
   $$Om de tijden op verschillende afstanden met elkaar te kunnen vergelijken, wordt elke tijd omgerekend naar de gemiddelde tijd per 500 meter. Stel bijvoorbeeld dat een schaatsster 15 minuten en 20,4 seconden over de 10 000 meter doet. Gemiddeld doet zij dan over 500 meter
((15 · 60 + 20,4) / 10 000) · 500 = 46,02 seconden$$, 'inline'),
  ('12fa3091-419d-427f-a0af-309c0d128df0', '98610a79-25e7-4def-9097-3ba6b2a52add', $$boxplots van de omgerekende tijden$$,
   $$wiskunde-a-havo-2022-ii-recordtijden-van-schaatssters-context6.png$$,
   $$Voor de vier langste afstanden worden de persoonlijke recordtijden van alle 86 schaatssters omgerekend naar de gemiddelde tijd per 500 meter. Deze omgerekende tijden zijn weergegeven in boxplots. Zie figuur 2. Deze figuur staat ook op de uitwerkbijlage.$$, 'inline'),
  ('38225537-d49f-48ae-a330-a5aa6a767217', '98610a79-25e7-4def-9097-3ba6b2a52add', $$figuur 2: boxplots omgerekende tijden$$,
   $$wiskunde-a-havo-2022-ii-recordtijden-van-schaatssters-context7.png$$,
   $$figuur 2
omgerekende tijd (gemiddelde tijd per 500 meter)
boxplots voor 10 000 m, 5000 m, 3000 m en 1500 m; horizontale as: omgerekende tijd (seconden), 38 t/m 58$$, 'inline'),
  ('a44194c5-a399-46c8-b47c-a089ccd5aa4c', '98610a79-25e7-4def-9097-3ba6b2a52add', $$groot verschil tussen 1500 m en 10 000 m$$,
   $$wiskunde-a-havo-2022-ii-recordtijden-van-schaatssters-context8.png$$,
   $$Als je de boxplots onderling vergelijkt, dan kun je met behulp van het formuleblad concluderen dat er een groot verschil is tussen de omgerekende tijden op de 1500 meter en die op de 10 000 meter. Er zijn meer afstanden waarbij er sprake is van een groot verschil.$$, 'inline'),
  ('2345b5a5-5d1a-4043-8aff-1557097c6f16', '98610a79-25e7-4def-9097-3ba6b2a52add', $$notatie van recordtijden in de tabel$$,
   $$wiskunde-a-havo-2022-ii-recordtijden-van-schaatssters-context9.png$$,
   $$In de tabel staan de persoonlijke recordtijden van twee van de 86 schaatssters. Zo zie je dat de persoonlijke recordtijd op de 1000 meter van Martina Sáblíková 1:15,86 is. Zij deed er dus 1 minuut, 15 seconden en 86 honderdsten van een seconde over.$$, 'inline'),
  ('50263576-c055-4819-b741-2182549bbd92', '98610a79-25e7-4def-9097-3ba6b2a52add', $$tabel: recordtijden Sáblíková en Farestveit$$,
   $$wiskunde-a-havo-2022-ii-recordtijden-van-schaatssters-context10.png$$,
   $$tabel
| Martina Sáblíková | Caroline Farestveit
recordtijd op de 500 meter in min:sec | 0:39,23 | 0:44,83
recordtijd op de 1000 meter in min:sec | 1:15,86 | 1:30,03
recordtijd op de 1500 meter in min:sec | 1:53,44 | 2:17,08
recordtijd op de 3000 meter in min:sec | 3:55,10 | 4:42,34
recordtijd op de 5000 meter in min:sec | 6:42,66 | 8:06,64
recordtijd op de 10 000 meter in min:sec | 13:48,33 | 16:54,71$$, 'inline'),
  ('bc0b08c2-5308-43c2-accb-11e855060865', '98610a79-25e7-4def-9097-3ba6b2a52add', $$Sáblíková: beste op 5000 m en 10 000 m$$,
   $$wiskunde-a-havo-2022-ii-recordtijden-van-schaatssters-context11.png$$,
   $$Sáblíková wordt gezien als een van de beste schaatssters ooit. Begin 2016 was zowel haar persoonlijke recordtijd op de 5000 meter als haar persoonlijke recordtijd op de 10 000 meter de beste van de 86 schaatssters. Met behulp van de tabel, figuur 1 en figuur 2 kun je ook voor andere afstanden onderzoeken of Sáblíková’s persoonlijke recordtijden de beste waren van deze 86 schaatssters.$$, 'inline'),
  ('1386412b-a9bb-4130-b847-a3589cbb0682', '98610a79-25e7-4def-9097-3ba6b2a52add', $$uitspraak van een fan van Farestveit$$,
   $$wiskunde-a-havo-2022-ii-recordtijden-van-schaatssters-context12.png$$,
   $$In de tabel staan ook de persoonlijke recordtijden van Caroline Farestveit. Een fan van Farestveit doet de volgende uitspraak: “Als je Farestveit vergelijkt met de 85 andere schaatssters, dan presteert Farestveit beter op de 10 000 meter dan op de 5000 meter.”$$, 'inline'),
