   $$wiskunde-a-havo-2022-ii-spoedeisende-ritten-van-ambulances-vraag6.png$$, $$4p 6 Geef voor elk van de vier variabelen in de tabel op de uitwerkbijlage aan welke soort variabele het betreft. Zet per variabele precies één kruisje.$$, array['0392c592-df8b-463f-92b3-8de30a1c3848', '881ed966-5288-4e2b-80d1-a729333a2a2b', '97c2f20a-6b51-4318-89ab-fc7e20fa34b8', '28dc308d-2af1-410e-9f16-1f07e5bc0961', 'ec8a44ed-28f4-40ed-95e9-c70eeb97f21c']::uuid[]),
  ('c9f0b2e2-6293-4ae0-a9bd-e0fd8fd1a829', 'bac1b2a5-9c72-4215-a361-ffaff53f2412', 7,
   '[{"domain": "Statistiek", "subdomain": "Data verwerken"}, {"domain": "Statistiek", "subdomain": "Presentaties van data interpreteren en beoordelen"}]'::jsonb,
